nav{display:flex;gap:30px;font-size:16px;font-weight:500}
nav a{padding:6px 0;position:relative}
nav a:hover,nav a.active{color:#c8102e}
nav a.active::after{content:"";position:absolute;left:0;right:0;bottom:-20px;height:3px;background:#c8102e}
.hero{display:grid;grid-template-columns:2fr 1fr;gap:16px;margin-top:20px}
