.section-head a.more{font-size:13px;color:#666}
.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.card{background:#fff;transition:transform .2s}
.card:hover{transform:translateY(-3px);box-shadow:0 6px 18px rgba(0,0,0,.08)}
.card .thumb{height:170px;background:linear-gradient(135deg,#3b6ea5,#1d3a5a)}
.card .thumb.t2{background:linear-gradient(135deg,#7a4a1f,#b7813a)}
