.newsflow .title{flex:1;font-size:15px}
.newsflow .title a:hover{color:#c8102e}
.newsflow .time{color:#999;font-size:13px;margin-left:16px}
.cols{display:grid;grid-template-columns:2fr 1fr;gap:28px;margin-top:36px}
.hot{background:#fff;padding:20px}
.hot h3{font-size:18px;font-weight:800;margin-bottom:12px;padding-bottom:10px;border-bottom:2px solid #222}
.hot ol{list-style:none;counter-reset:hot}
.hot li{counter-increment:hot;padding:10px 0;border-bottom:1px dashed #eee;font-size:14px}
.hot li:last-child{border-bottom:none}
.hot li::before{content:counter(hot);color:#999;margin-right:10px;font-weight:700}
.hot li:nth-child(-n+3)::before{color:#c8102e}
.hot li a:hover{color:#c8102e}
.about-box{background:#fff;padding:20px;margin-top:16px}
