.about-box a.btn{display:inline-block;margin-top:14px;background:#c8102e;color:#fff;padding:8px 18px;font-size:13px}
footer{background:#1a1a1a;color:#999;margin-top:48px;padding:32px 0;font-size:13px}
footer .container{display:flex;justify-content:space-between;flex-wrap:wrap;gap:16px}
footer a{color:#bbb;margin-right:18px}
footer a:hover{color:#fff}
@media(max-width:900px){
.hero,.cols{grid-template-columns:1fr}
.grid{grid-template-columns:1fr 1fr}
nav{font-size:14px;gap:16px}
}
@media(max-width:600px){
.grid{grid-template-columns:1fr}
nav{display:none}
}
</style>
</head>
